  // app/javascript/controllers/library/percentage_counter_controller.js
  var percentage_counter_controller_default = class extends Controller {
    connect() {
      this.step = parseInt(this.data.get("steps") || "1", 10);
      this.percentage = 0;
      this.startTime = Date.now();
      this.setDurationsBasedOnStep(this.step);
      this.updatePercentage();
      if ($("#messages")[0]) {
        $("#messages").scrollTop($("#messages")[0].scrollHeight);
      }
    }
    setDurationsBasedOnStep(step) {
      const baseDuration = 12e3;
      const multiplier = this.getDurationMultiplier(step);
      this.fastIncrementDuration = 5e3 * multiplier;
      this.endTime = this.startTime + baseDuration * multiplier;
    }
    getDurationMultiplier(step) {
      switch (step) {
        case 4:
          return 2;
        case 9:
          return 3;
        case 16:
          return 4;
        default:
          return 1;
      }
    }
    updatePercentage() {
      const now3 = Date.now();
      if (this.hasDisplayTarget) {
        if (this.percentage < 95) {
          const elapsedTime = now3 - this.startTime;
          const fastIncrementTimePerPercent = this.fastIncrementDuration / 95;
          if (elapsedTime >= this.percentage * fastIncrementTimePerPercent) {
            this.displayTarget.innerText = `${this.percentage}%`;
            this.percentage += 1;
          }
          requestAnimationFrame(() => this.updatePercentage());
        } else if (this.percentage >= 95 && this.percentage < 100) {
          this.displayTarget.innerText = `${this.percentage}%`;
          const remainingTime = this.endTime - now3;
          const remainingPercentage = 100 - this.percentage;
          const delay = remainingTime / remainingPercentage;
          this.percentage += 1;
          setTimeout(() => this.updatePercentage(), delay);
        } else if (this.percentage === 100) {
          this.displayTarget.innerText = "100%";
        }
      }
    }
  };
