  function toggleModalVisibility(modalId, action) {
    const modalElement = document.getElementById(modalId);
    if (modalElement) {
      const eventName = `${action}`;
      const event = new CustomEvent(eventName, { bubbles: true });
      modalElement.dispatchEvent(event);
    }
  }
  function scrollToBottom(element) {
    const totalHeight = element.scrollHeight - element.clientHeight;
    let start3 = null;
    const duration2 = 500;
    const easeOutQuad = (t2) => t2 * (2 - t2);
    const step = (timestamp) => {
      if (!start3)
        start3 = timestamp;
      const progress2 = Math.min(1, (timestamp - start3) / duration2);
      const easedProgress = easeOutQuad(progress2);
      const currentScroll = element.scrollTop + (totalHeight - element.scrollTop) * easedProgress;
      element.scrollTop = currentScroll;
      if (progress2 < 1) {
        window.requestAnimationFrame(step);
      }
    };
    window.requestAnimationFrame(step);
  }

